insert into public.travel_packages (id,status,data) values ('lahaul-expedition','published','{"id":"lahaul-expedition","title":"Lahaul Valley Expedition","homeTitle":"Lahaul Valley Expedition","destination":"Himachal Pradesh","route":["Manali","Atal Tunnel","Sissu","Tandi","Jispa","Baralacha La"],"nights":5,"price":15000,"image":"lahaul-poster.jpeg","style":"Adventure","days":["Delhi departure · Overnight journey to Manali","Arrive in Manali · Hadimba, Vashisht, Manu Temple, Mall Road and Old Manali · Stay in Manali","Manali → Atal Tunnel → Sissu → Keylong → Jispa · Camp, bonfire and stargazing","Jispa → Baralacha La → Deepak Tal → Sissu · Overnight in Sissu","Breakfast · Sissu to Kasol · Riverside and local market time · Overnight in Kasol","Manikaran visit · Return journey to Delhi"],"description":"A six-day mountain circuit through Manali, Lahaul and Kasol. Our June 2026 departure was advertised from ₹15,000 per person for a 20-traveller group in premium Urbania AC. Those dates have passed; ask us for current dates, route access and a fresh quote.","status":"published","departures":[],"attachments":[],"indicative":true,"pastTrip":true}'::jsonb) on conflict (id) do nothing;
insert into public.travel_packages (id,status,data) values ('udaipur-jawai','published','{"id":"udaipur-jawai","title":"Udaipur & Jawai: Heritage, Hills and Wildlife","homeTitle":"Udaipur & Jawai","destination":"Rajasthan","route":["Udaipur","Alsigarh","Raita Hills","Bahubali Hills","Jawai"],"nights":3,"price":0,"image":"udaipur-poster.jpeg","style":"Wildlife & culture","days":["Explore Udaipur · City Palace, Jagdish Temple, local market and Fateh Sagar Lake · Overnight in Udaipur","Scenic Udaipur excursion to Alsigarh, Raita Hills and Bahubali Hills · Overnight in Udaipur","Drive to Jawai · Check in at camp or resort · Leopard safari, bonfire and dinner · Overnight in Jawai","Breakfast · Leisure time at camp · Return journey to Udaipur"],"description":"A four-day Udaipur and Jawai itinerary combining city heritage, the Aravalli hills, a leopard safari and a high-tea experience. Safari sightings and activities depend on local conditions. Request current dates and pricing.","status":"published","departures":[],"attachments":[],"indicative":true,"pastTrip":true,"priceOnRequest":true}'::jsonb) on conflict (id) do nothing;
insert into public.travel_packages (id,status,data) values ('chandratal-expedition','published','{"id":"chandratal-expedition","title":"Chandrataal Weekend Expedition","homeTitle":"Chandrataal Weekend","destination":"Himachal Pradesh","route":["Delhi","Manali","Atal Tunnel","Koksar","Chandrataal"],"nights":3,"price":0,"image":"chandratal-poster.jpeg","style":"Adventure","days":["Evening departure from Delhi · Overnight journey to Manali","Arrive in Manali · Check in and rest · Optional Hadimba Temple, Vashisht and Mall Road · Overnight in Manali","Early breakfast · Travel via Atal Tunnel, Koksar, Chhatru and Batal to Chandrataal · Camp overnight, subject to seasonal road access","Early breakfast · Return towards Manali · Visit Anjani Mahadev if conditions allow · Evening departure for Delhi","Arrive in Delhi in the morning"],"description":"A seasonal Chandrataal camping trip via Manali, Atal Tunnel, Koksar, Chhatru and Batal. The route and camp access depend on road, weather and seasonal opening conditions. Request current dates, inclusions and pricing before planning.","status":"published","departures":[],"attachments":[],"indicative":true,"pastTrip":true,"priceOnRequest":true}'::jsonb) on conflict (id) do nothing;
